const WS = /\s/;
function isSpace(ch) {
  return ch !== undefined && WS.test(ch);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function setOwn(obj, key, value) {
  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
}

/** Split text into physical lines, honouring LF, CRLF and lone CR terminators. */
function splitLines(text) {
  const lines = [];
  let start = 0;
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '\n') {
      lines.push(text.slice(start, i));
      i += 1;
      start = i;
    } else if (ch === '\r') {
      lines.push(text.slice(start, i));
      i += 1;
      if (text[i] === '\n') i += 1;
      start = i;
    } else {
      i += 1;
    }
  }
  if (start < text.length) lines.push(text.slice(start));
  return lines;
}

/**
 * Parse one quoted token starting at s[pos] === '"'.
 * @returns {{ value: string, end: number }}
 */
function parseQuoted(s, pos, lineNo) {
  let i = pos + 1;
  let out = '';
  for (;;) {
    if (i >= s.length) throw new IniError('unterminated quoted string', lineNo);
    const ch = s[i];
    if (ch === '"') return { value: out, end: i + 1 };
    if (ch === '\\') {
      i += 1;
      if (i >= s.length) throw new IniError('unterminated quoted string', lineNo);
      const esc = s[i];
      switch (esc) {
        case '\\':
          out += '\\';
          i += 1;
          break;
        case '"':
          out += '"';
          i += 1;
          break;
        case 'n':
          out += '\n';
          i += 1;
          break;
        case 'r':
          out += '\r';
          i += 1;
          break;
        case 't':
          out += '\t';
          i += 1;
          break;
        case '0':
          out += '\0';
          i += 1;
          break;
        case ';':
          out += ';';
          i += 1;
          break;
        case '#':
          out += '#';
          i += 1;
          break;
        case '=':
          out += '=';
          i += 1;
          break;
        case '[':
          out += '[';
          i += 1;
          break;
        case ']':
          out += ']';
          i += 1;
          break;
        case 'u': {
          const hex = s.slice(i + 1, i + 5);
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw new IniError(`invalid unicode escape: \\u${hex}`, lineNo);
          }
          out += String.fromCharCode(parseInt(hex, 16));
          i += 5;
          break;
        }
        default:
          throw new IniError(`unknown escape sequence: \\${esc}`, lineNo);
      }
    } else {
      out += ch;
      i += 1;
    }
  }
}

function parseHeaderName(s, lineNo) {
  let pos = 1;
  while (pos < s.length && isSpace(s[pos])) pos += 1;
  let name;
  if (s[pos] === '"') {
    const { value, end } = parseQuoted(s, pos, lineNo);
    let p = end;
    while (p < s.length && isSpace(s[p])) p += 1;
    if (s[p] !== ']') {
      if (p >= s.length) throw new IniError('unterminated section header', lineNo);
      throw new IniError('unexpected text after quoted section name', lineNo);
    }
    p += 1;
    while (p < s.length && isSpace(s[p])) p += 1;
    if (p !== s.length) throw new IniError('unexpected text after quoted section name', lineNo);
    name = value;
  } else {
    if (!s.endsWith(']')) throw new IniError('unterminated section header', lineNo);
    name = s.slice(1, -1).trim();
  }
  if (name === '') throw new IniError('empty section name', lineNo);
  return name;
}

function parseEntry(s, lineNo) {
  let key;
  let pos;
  if (s[0] === '"') {
    const { value, end } = parseQuoted(s, 0, lineNo);
    key = value;
    let p = end;
    while (p < s.length && isSpace(s[p])) p += 1;
    if (p >= s.length) throw new IniError("missing '=' in entry", lineNo);
    if (s[p] !== '=') throw new IniError('unexpected text after quoted key', lineNo);
    pos = p + 1;
  } else {
    const eq = s.indexOf('=');
    if (eq === -1) throw new IniError("missing '=' in entry", lineNo);
    key = s.slice(0, eq).trim();
    pos = eq + 1;
  }
  if (key === '') throw new IniError('empty key', lineNo);

  let p3 = pos;
  while (p3 < s.length && isSpace(s[p3])) p3 += 1;
  let value;
  if (p3 < s.length && s[p3] === '"') {
    const { value: v, end } = parseQuoted(s, p3, lineNo);
    let p4 = end;
    while (p4 < s.length && isSpace(s[p4])) p4 += 1;
    if (p4 !== s.length) throw new IniError('unexpected text after quoted value', lineNo);
    value = v;
  } else {
    value = s.slice(p3).trim();
  }
  return { key, value };
}

function applyDuplicate(body, key, value, duplicates, lineNo) {
  if (!hasOwn(body, key)) {
    setOwn(body, key, value);
    return;
  }
  switch (duplicates) {
    case 'last':
      setOwn(body, key, value);
      break;
    case 'first':
      break;
    case 'array': {
      const existing = body[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        setOwn(body, key, [existing, value]);
      }
      break;
    }
    case 'error':
      throw new IniError(`duplicate key: ${key}`, lineNo);
    default:
      break;
  }
}

