    const first = trimmed[0];
    if (first === ';' || first === '#') continue;
    if (first === '[') {
      const name = parseHeaderName(trimmed, lineNo);
      if (!hasOwn(sections, name)) setOwn(sections, name, {});
      currentBody = sections[name];
      continue;
    }
    const { key, value } = parseEntry(trimmed, lineNo);
    applyDuplicate(currentBody, key, value, duplicates, lineNo);
  }

  return { global, sections };
}

