  let out = '';
  for (const ch of s) {
    switch (ch) {
      case '\\':
        out += '\\\\';
        break;
      case '"':
        out += '\\"';
        break;
      case '\n':
        out += '\\n';
        break;
      case '\r':
        out += '\\r';
        break;
      case '\t':
        out += '\\t';
        break;
      case '\0':
        out += '\\0';
        break;
      default:
        out += ch;
    }
  }
  return out;
}

function needsValueQuote(v) {
  if (v === '') return true;
  if (v.trim() !== v) return true;
  if (v.startsWith('[')) return true;
  if (/["\\\n\r\t\0;#=]/.test(v)) return true;
  return false;
}

function needsKeyQuote(k) {
  if (k === '') return true;
  if (k.trim() !== k) return true;
  if (k.startsWith('[')) return true;
  if (/["\\\n\r\t\0;#=[\]]/.test(k)) return true;
  return false;
}

function needsSectionQuote(name) {
  if (name === '') return true;
  if (name.trim() !== name) return true;
  if (/["\\\n\r\t\0[\]]/.test(name)) return true;
  return false;
}

/**
 * Serialise one value as it would appear to the right of `=`.
 *
 * @param {string} value value text
 * @returns {string} quoted token when quoting is required, otherwise the value itself
 */
export function formatValue(value) {
  return needsValueQuote(value) ? `"${quoteEscape(value)}"` : value;
}

/**
 * Serialise one key as it would appear to the left of `=`.
 *
 * @param {string} key key text
 * @returns {string} quoted token when quoting is required, otherwise the key itself
 */
export function formatKey(key) {
  return needsKeyQuote(key) ? `"${quoteEscape(key)}"` : key;
}

function formatSectionName(name) {
  return needsSectionQuote(name) ? `"${quoteEscape(name)}"` : name;
}

/**
 * Serialise a parsed document back to INI text.
 *
 * @param {{ global?: Record<string, string | string[]>, sections?: Record<string, Record<string, string | string[]>> }} data
 *   document to write
 * @param {{ eol?: string }} [options] line terminator, `'\n'` by default
 * @returns {string} INI text, empty when the document has no entries
 */
export function stringify(data, options = {}) {
  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
    throw new IniError('document must be an object');
  }
  const eol = options.eol ?? '\n';
  const global = data.global ?? {};
  const sections = data.sections ?? {};
  const lines = [];

  function emitEntries(obj) {
    for (const key of Object.keys(obj)) {
      if (key === '') throw new IniError('empty key');
      const fKey = formatKey(key);
      const value = obj[key];
      if (Array.isArray(value)) {
        for (const v of value) {
          if (typeof v !== 'string') throw new IniError('value must be a string');
          lines.push(`${fKey}=${formatValue(v)}`);
        }
      } else {
        if (typeof value !== 'string') throw new IniError('value must be a string');
        lines.push(`${fKey}=${formatValue(value)}`);
      }
    }
  }

  emitEntries(global);
  for (const name of Object.keys(sections)) {
    if (name === '') throw new IniError('empty section name');
    if (lines.length > 0) lines.push('');
    lines.push(`[${formatSectionName(name)}]`);
    emitEntries(sections[name]);
  }

  if (lines.length === 0) return '';
  return lines.join(eol) + eol;
}
