 *

diffs.newText:
 *   keys seen before the first header, and one body per section header
 */
export function parse(text, options = {}) {
  if (typeof text !== 'string') throw new IniError('input must be a string');
  const duplicates = options.duplicates ?? 'last';
  if (!['last', 'first', 'error', 'array'].includes(duplicates)) {
    throw new IniError(`unknown duplicates policy: ${duplicates}`);
  }

  const global = {};
  const sections = {};
  let currentBody = global;

  const lines = splitLines(text);
  for (let idx = 0; idx < lines.length; idx += 1) {
    const raw = lines[idx];
    const lineNo = idx + 1;
    const trimmed = raw.trim();
    if (trimmed === '') continue;
    const first = trimmed[0];
    if (first === ';' || first === '#') continue;
    if (first === '[') {
      const name = parseHeaderName(trimmed, lineNo);
      if (!hasOwn(sections, name)) setOwn(sections, name, {});
      currentBody = sections[name];
      continue;
    }
    const { key, value } = parseEntry(trimmed, lineNo);
    applyDuplicate(currentBody, key, value, duplicates, lineNo);
  }

  return { global, sections };
}

function quoteEscape(s) {
  let out = '';
  for (const ch of s) {
    switch (ch) {
      case '\\':
        out += '\\\\';
        break;
      case '"':
        out += '\\"';
        break;
      case '\n':
        out += '\\n';
        break;
      case '\r':
        out += '\\r';
        break;
      case '\t':
        out += '\\t';
        break;
      case '\0':
        out += '\\0';
        break;
      default:
        out += ch;
    }
  }
  return out;
}

function needsValueQuote(v) {
  if (v === '') return true;
  if (v.trim() !== v) return true;
  if (v.startsWith('[')) return true;
  if (/["\\\n\r\t\0;#=]/.test(v)) return true;
  return false;
}

function needsKeyQuote(k) {
  if (k === '') return true;
  if (k.trim() !== k) return true;
  if (k.startsWith('[')) return true;
  if (/["\\\n\r\t\0;#=[\]]/.test(k)) return true;
  return false;
}

function needsSectionQuote(name) {
  if (name === '') return true;
  if (name.trim() !== name) return true;
  if (/["\\\n\r\t\0[\]]/.test(name)) return true;
  return false;
}

